/* ============================================================
 * MTW core/data-units.js
 * 单位定义：RAW 表 + U() 工厂 + UNIT_DEFS + DEF_BY_ID
 * 依赖：data-weapons.js（wpn()）
 * ============================================================ */
'use strict';

/* ---------- U() 工厂 ---------- */
const UNIT_DEFS = [];
function U(id, name, nat, cat, ech, men, mob, mp, armor, weaponNames,
           sens, ew, mor, trn, stl, pts, desc, opt) {
  opt = opt || {};
  UNIT_DEFS.push({
    id, name, nation: nat, cat, echelon: ech, men, mob, mp,
    armor: {f: armor[0], s: armor[1], t: armor[2]},
    aps: opt.aps || 0,
    era: opt.era || 0,
    addArmor: opt.addArmor || 0,
    carry: opt.carry || 0,
    weapons: weaponNames.map(n => {
      const w = wpn(n);
      return {
        n: w[0], t: w[1], r: w[2], pen: w[3], acc: w[4], rof: w[5], ammo: w[6],
        guid: w[7] || 0, top: w[8] || 0, sup: w[9] || 0, band: w[10] || ''
      };
    }),
    sens: {v: sens[0], t: sens[1], radar: sens[2], sig: sens[3]},
    ew: {jam: ew[0], eccm: ew[1], decoy: ew[2]},
    morale: mor, training: trn, stealth: stl, pts, d: desc,
    cap: opt.cap || ''
  });
}

